from PIL import Image
import numpy as np
from scipy.ndimage import gaussian_filter
im=np.asarray(Image.open('/app/target.png').convert('RGB'),dtype=float)/255
hexes=['9eb0a0','95964b','728c73','718680','6d828d','677e9c','707636','787224','646554','505d63','5f572f','4f571d','414b41','41472c','2c3d40','253228'];pal=np.array([[int(h[i:i+2],16)/255 for i in (0,2,4)] for h in hexes])
def lab(rgb):
 x=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4);M=np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.0721750],[.0193339,.1191920,.9503041]]);xyz=x@M.T/np.array([.95047,1.,1.08883]);f=np.where(xyz>(6/29)**3,np.cbrt(xyz),xyz/(3*(6/29)**2)+4/29);return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
T=lab(im);P=lab(pal); T=np.stack([gaussian_filter(T[:,:,i],8) for i in range(3)],-1)
for cell in [16,20,24]:
 for mincells in [2,3,4]:
  n=0; r=[]
  for v in range(10,1024,20):
   ids=[]
   for u in range(0,1024,cell):
    a=T[max(0,v-20):min(1024,v+21),u:min(1024,u+cell)].mean((0,1)); ids.append(np.argmin(((P-a)**2).sum(1)))
   runs=[]; st=0
   for i in range(1,len(ids)+1):
    if i==len(ids) or ids[i]!=ids[st]: runs.append([ids[st],st,i]);st=i
   changed=True
   while changed:
    changed=False
    for j,(c,s,e) in enumerate(runs):
     if e-s<mincells and len(runs)>1:
      ni=0 if j==0 else len(runs)-1 if j==len(runs)-1 else (j-1 if np.linalg.norm(P[runs[j-1][0]]-P[c])<np.linalg.norm(P[runs[j+1][0]]-P[c]) else j+1)
      runs[ni][1]=min(runs[ni][1],s);runs[ni][2]=max(runs[ni][2],e);runs.pop(j);changed=True;break
   n+=len(runs);r.append(len(runs))
  print(cell,mincells,n,round(np.mean(r),1))
